namespace {

using JobStatus = SCE::Generated::JobStatus::JobStatusPayload;
using OrderLine = SCE::Generated::OrderLine::OrderLinePayload;
using Card = SCE::Generated::CardPayment::CardPaymentPayload;
using Color = SCE::Generated::PaintColor::PaintColor;

namespace EveryMatcher = SCE::Generated::EveryMatcher;

// U+00E9, one character of two UTF-8 bytes.
const std::string E_ACUTE = "\xC3\xA9";

/// `text` repeated `times` times.
std::string repeated(const std::string &text, int times) {
    std::string out;
    for (int i = 0; i < times; ++i) {
        out += text;
    }
    return out;
}

/// A job status every_matcher matches with the limit 100: each field at a value
/// its matcher holds, each optional field absent.
JobStatus matching() {
    JobStatus status;
    status.elapsed_ms = 1;
    status.note = std::nullopt;
    status.codes = {3, 9, 5};
    status.tag = std::nullopt;
    status.retry = std::nullopt;
    status.count = 100;
    return status;
}

constexpr std::uint32_t LIMIT = 100;

TEST(ATestTemplate, MatchesAStatusEachOfWhoseFieldsItsMatcherHolds) {
    EXPECT_TRUE(EveryMatcher::match(matching(), LIMIT));
}

// value-list (B.1.2.1) of a specific value and a range (B.1.2.5), both bounds
// inclusive, the upper one a formal parameter.
TEST(ATestTemplate, AValueListMatchesAnyOfItsItemsAndARangeHoldsItsBounds) {
    for (const std::uint32_t elapsed : {1u, 10u, 50u, LIMIT}) {
        JobStatus status = matching();
        status.elapsed_ms = elapsed;
        EXPECT_TRUE(EveryMatcher::match(status, LIMIT)) << elapsed;
    }
    for (const std::uint32_t elapsed : {0u, 2u, 9u, LIMIT + 1}) {
        JobStatus status = matching();
        status.elapsed_ms = elapsed;
        EXPECT_FALSE(EveryMatcher::match(status, LIMIT)) << elapsed;
    }
}

// any-value with ifpresent (B.1.4.2) and a length restriction (B.1.4.1) on an
// optional text: absent, or present with at most eight characters.
TEST(ATestTemplate, IfpresentTakesAnAbsentFieldAndALengthCountsCharacters) {
    JobStatus status = matching();
    status.note = std::nullopt;
    EXPECT_TRUE(EveryMatcher::match(status, LIMIT));
    status.note = std::string("abcdefgh");
    EXPECT_TRUE(EveryMatcher::match(status, LIMIT));
    status.note = std::string("abcdefghi");
    EXPECT_FALSE(EveryMatcher::match(status, LIMIT));
    // Eight characters of two bytes each: sixteen bytes, eight characters.
    status.note = repeated(E_ACUTE, 8);
    EXPECT_TRUE(EveryMatcher::match(status, LIMIT));
    status.note = repeated(E_ACUTE, 9);
    EXPECT_FALSE(EveryMatcher::match(status, LIMIT));
}

// list-match (B.1.1): exactly three elements, the first 3, the second any
// value (B.1.3.1), the third not 0 (complement, B.1.2.2).
TEST(ATestTemplate, AListMatchHoldsItsCountAndEachElementInOrder) {
    for (const std::vector<std::uint8_t> &codes :
         {std::vector<std::uint8_t>{3, 9, 5}, std::vector<std::uint8_t>{3, 0, 1}}) {
        JobStatus status = matching();
        status.codes = codes;
        EXPECT_TRUE(EveryMatcher::match(status, LIMIT));
    }
    for (const std::vector<std::uint8_t> &codes :
         {std::vector<std::uint8_t>{3, 9, 0}, std::vector<std::uint8_t>{4, 9, 5}, std::vector<std::uint8_t>{3, 9},
          std::vector<std::uint8_t>{3, 9, 5, 5}, std::vector<std::uint8_t>{}}) {
        JobStatus status = matching();
        status.codes = codes;
        EXPECT_FALSE(EveryMatcher::match(status, LIMIT)) << codes.size();
    }
}

// any-value-or-none (B.1.2.4) and omit (B.1.2.8).
TEST(ATestTemplate, AnyValueOrNoneTakesBothAndOmitOnlyAnAbsentField) {
    JobStatus status = matching();
    status.tag = std::uint8_t{7};
    EXPECT_TRUE(EveryMatcher::match(status, LIMIT));
    status.tag = std::nullopt;
    EXPECT_TRUE(EveryMatcher::match(status, LIMIT));
    status.retry = std::uint8_t{1};
    EXPECT_FALSE(EveryMatcher::match(status, LIMIT));
}

// template-ref (-1 §15.1): the referenced template's match, its formal
// parameter bound to this template's own.
TEST(ATestTemplate, AReferenceMatchesByItsTemplateWithTheArgumentItBinds) {
    JobStatus status = matching();
    status.count = 150;
    EXPECT_FALSE(EveryMatcher::match(status, LIMIT));
    EXPECT_TRUE(EveryMatcher::match(status, 150));
    EXPECT_TRUE(SCE::Generated::ElapsedAtMost::match(150, 150));
    EXPECT_FALSE(SCE::Generated::ElapsedAtMost::match(151, 150));
}

// A specific template's value (§6.2) matches the template, and a value that
// differs in one field does not.
TEST(ATestTemplate, ASpecificTemplatesValueMatchesItsTemplate) {
    namespace JobReport = SCE::Generated::JobReport;
    const JobStatus report = JobReport::value();
    EXPECT_EQ(report.elapsed_ms, 0u);
    EXPECT_EQ(report.note, std::optional<std::string>("started on time"));
    EXPECT_EQ(report.codes, (std::vector<std::uint8_t>{7}));
    EXPECT_FALSE(report.tag.has_value());
    EXPECT_FALSE(report.retry.has_value());
    EXPECT_EQ(report.count, 1u);
    EXPECT_TRUE(JobReport::match(report));

    JobStatus absent = report;
    absent.note = std::nullopt;
    EXPECT_FALSE(JobReport::match(absent));
    JobStatus retried = report;
    retried.retry = std::uint8_t{0};
    EXPECT_FALSE(JobReport::match(retried));
    JobStatus counted = report;
    counted.count = 2;
    EXPECT_FALSE(JobReport::match(counted));
}

// A specific template whose values are partly its parameters.
TEST(ATestTemplate, ASpecificTemplatesValueHoldsTheParametersItIsGiven) {
    namespace JobReportOf = SCE::Generated::JobReportOf;
    const std::string note = "late";
    const JobStatus report = JobReportOf::value(5, note, std::uint8_t{9});
    EXPECT_EQ(report.elapsed_ms, 5u);
    EXPECT_EQ(report.note, std::optional<std::string>(note));
    EXPECT_EQ(report.codes, (std::vector<std::uint8_t>{9, 255}));
    EXPECT_FALSE(report.tag.has_value());
    EXPECT_EQ(report.retry, std::optional<std::uint8_t>(2));
    EXPECT_EQ(report.count, 4294967295u);
    EXPECT_TRUE(JobReportOf::match(report, 5, note, std::uint8_t{9}));
    EXPECT_FALSE(JobReportOf::match(report, 6, note, std::uint8_t{9}));
    EXPECT_FALSE(JobReportOf::match(report, 5, std::string("early"), std::uint8_t{9}));
    EXPECT_FALSE(JobReportOf::match(report, 5, note, std::uint8_t{8}));
}

// An enum literal, and a reference to a specific template, which builds the
// field with that template's value.
TEST(ATestTemplate, AnEnumLiteralAndAReferenceToASpecificTemplateBuildAndMatch) {
    namespace OrderLineExact = SCE::Generated::OrderLineExact;
    const OrderLine line = OrderLineExact::value();
    EXPECT_EQ(line.sku, "A-1");
    EXPECT_EQ(line.quantity, std::uint16_t{2});
    EXPECT_EQ(line.color, Color::Red);
    EXPECT_TRUE(OrderLineExact::match(line));

    OrderLine blue = line;
    blue.color = Color::Blue;
    EXPECT_FALSE(OrderLineExact::match(blue));
    OrderLine three = line;
    three.quantity = 3;
    EXPECT_FALSE(OrderLineExact::match(three));
}

// A reference whose template matches a range up to the argument it binds.
TEST(ATestTemplate, AReferenceToARangeHoldsTheBoundItsArgumentGives) {
    namespace OrderLineBounded = SCE::Generated::OrderLineBounded;
    OrderLine line;
    line.sku = "A-1";
    line.quantity = 5;
    line.color = Color::Blue;
    EXPECT_TRUE(OrderLineBounded::match(line, std::uint16_t{5}));
    EXPECT_FALSE(OrderLineBounded::match(line, std::uint16_t{4}));
    line.color = Color::Green;
    EXPECT_FALSE(OrderLineBounded::match(line, std::uint16_t{5}));
}

// A template that is specific in itself and references one that is not
// matches by the referenced template's range.
TEST(ATestTemplate, ATemplateMatchesThroughAReferenceToOneThatIsNotSpecific) {
    namespace ReportWithin = SCE::Generated::ReportWithin;
    JobStatus status = SCE::Generated::JobReport::value();
    status.count = 60;
    EXPECT_TRUE(ReportWithin::match(status, 60));
    EXPECT_FALSE(ReportWithin::match(status, 59));
}

// A length restriction on a text counts characters, so a text whose bytes
// pass its upper bound matches while its characters do not; a range with a
// literal lower bound.
TEST(ATestTemplate, ALengthOnATextCountsAMultiByteCharacterAsOne) {
    namespace CardWithin = SCE::Generated::CardWithin;
    Card card;
    card.amount = 50;
    // Two characters in three bytes, and in four.
    for (const std::string &last4 : {E_ACUTE + "1", repeated(E_ACUTE, 2), std::string("123")}) {
        card.last4 = last4;
        EXPECT_TRUE(CardWithin::match(card, 100)) << last4.size();
    }
    for (const std::string &last4 : {std::string("1"), E_ACUTE, std::string("1234")}) {
        card.last4 = last4;
        EXPECT_FALSE(CardWithin::match(card, 100)) << last4.size();
    }
    card.last4 = "12";
    card.amount = 1;
    EXPECT_TRUE(CardWithin::match(card, 100));
    card.amount = 0;
    EXPECT_FALSE(CardWithin::match(card, 100));
    card.amount = 100;
    EXPECT_TRUE(CardWithin::match(card, 100));
    card.amount = 101;
    EXPECT_FALSE(CardWithin::match(card, 100));
}

// A byte string written in hex.
TEST(ATestTemplate, AByteStringLiteralIsItsOctets) {
    namespace VoucherIs = SCE::Generated::VoucherIs;
    const auto voucher = VoucherIs::value();
    EXPECT_EQ(voucher.voucher_code, (std::vector<std::uint8_t>{0x00, 0xff, 0x10, 0xa0}));
    EXPECT_TRUE(VoucherIs::match(voucher));
    auto other = voucher;
    other.voucher_code[3] = 0xa1;
    EXPECT_FALSE(VoucherIs::match(other));
}

}  // namespace
